WITH valid_orders AS (SELECT *, shipping_fee - discount shipping_fee_minus_discount FROM orders WHERE status = 'PENDING'), orders_stats AS (SELECT DATE_TRUNC('MONTH', order_date) order_month, channel, COUNT(*) cnt, COUNT(DISTINCT amount) unique_statuss FROM valid_orders GROUP BY DATE_TRUNC('MONTH', order_date), channel) SELECT order_month, channel, cnt FROM orders_stats WHERE unique_statuss < 9 ORDER BY cnt DESC;
